_zanim_cmd_hdr* CTAction::Parse(_zrdr* reader)
{
	/* 0x2be520 (written, untested): "action" (a valve of the anim being loaded), "state"
	 * (the value wanted, 0xffff when not given), "auto_return"; no action: no record */
	u32 state = 0xffff;
	bool autoReturn = false;
	char *action = zrdr_findstring(reader, "action");
	zrdr_finduint(reader, "state", &state, 1);
	zrdr_findbool(reader, "auto_return", &autoReturn);

	if (action == NULL)
		return NULL;

	TASK_ACTION *task = (TASK_ACTION *)task_alloc(16, *(u16 *)&ai_cmdid[0]);
	task->m_valve = ZAnim.m_CurAnim->AddValve(action);
	task->m_state = (u16)state;
	task->m_auto_return = autoReturn ? 1 : 0;
	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__8CTActionFP14_zanim_cmd_hdrPf */
bool CTAction::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2be2f0: the AI uses the node action whose valve is the anim's valve m_valve until the
	 * valve has m_state (STATE_ACTION); with auto_return a GOTO back to where it stands is
	 * pushed under it first. Always done at once (the frame's time used up) */
	TASK_ACTION *task = reinterpret_cast<TASK_ACTION *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (ai != NULL)
	{
		CNodeAction *action = CNodeAction::FindActionByValve(ZAnim.m_CurAnim->GetValve(task->m_valve));

		if (action != NULL)
		{
			if (task->m_auto_return && ai->PushAiState(STATE_GOTO, true))
			{
				CAiState *top = ai->GetAiState();
				CAiSGoto *go = top->m_state == STATE_GOTO ? static_cast<CAiSGoto *>(top) : NULL;

				if (go != NULL) /* port: NULL-tested (ELF writes through it) */
				{
					go->m_dest = ai->m_entity->m_mapLocValid;
					go->m_setup = 1;
				}
			}

			if (ai->PushAiState(STATE_ACTION, true))
			{
				CAiState *top = ai->GetAiState();
				CAiSAction *act = top->m_state == STATE_ACTION ? static_cast<CAiSAction *>(top) : NULL;

				if (act != NULL) /* port: NULL-tested (ELF writes through it) */
				{
					act->m_action = action;
					act->m_value = task->m_state;
					act->m_setup = 1;
				}
			}
		}
	}

	*dT = 0.0f;
	return true;
}

/* @socom-skeleton body Parse__6CTCommFP5_zrdr */
_zanim_cmd_hdr* CTComm::Parse(_zrdr* reader)
{
	/* 0x2be230 (written, untested): "team" (-1 none), "cmd" (CSealCtrl::GetCommandId) */
	TASK_COMM *task = (TASK_COMM *)task_alloc(16, *(u16 *)&ai_cmdid[0]);
	task->m_team = -1;
	task->m_cmd = 0;
	zrdr_findint(reader, "team", &task->m_team, 1);
	task->m_cmd = (u8)CSealCtrl::GetCommandId(zrdr_findstring(reader, "cmd"));
	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__6CTCommFP14_zanim_cmd_hdrPf */
bool CTComm::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2bde00: a team order. 27: every AI seal of the team wakes up (SetSleeping false; all
	 * five m8 uses: team 8, the sleeping reinforcements); 26: with a living target of its own
	 * the select's AI raises every AI of the team to AIA_GENERAL. Any command but 0 is then
	 * issued to the team's unit (IssueCommand, with the select's seal and the target). Done at
	 * once, the frame's time used up. */
	TASK_COMM *task = reinterpret_cast<TASK_COMM *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;
	u8 cmd = (u8)task->m_cmd;
	CEntity *target = NULL;

	if (cmd == 0)
	{
		*dT = 0.0f;
		return true;
	}

	if (cmd == 26 || cmd == 27)
	{
		CEntity *cur = ai != NULL ? ai->m_target.m_target.m_ent : NULL;

		if (cmd == 26 && (cur == NULL || !cur->m_isAlive))
			goto issue;

		if (cmd == 26)
			target = cur;

		for (std::list<CEntity*>::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
		{
			CEntity *e = *it;
			CZSealBody *s = e != NULL && (u8)e->m_type == 2 ? static_cast<CZSealBody *>(e) : NULL;

			if (s == NULL || !((1u << task->m_team) & s->m_team))
				continue;

			CSealCtrl *ctrl = static_cast<CSealCtrl *>(s->m_control);

			if (ctrl == NULL || !ctrl->IsAi())
				continue;

			if (cmd == 26)
			{
				ai->Debug("Setting (%s) AIA_GENERAL\n", s->m_node->m_name);
				ctrl->GetSealCtrlAi()->SetAiAware(AIA_GENERAL, NULL);
			}
			else
			{
#ifdef SOCOM_PORT
				SOCOM_PORT_TRACE("AI: COMM wake: %s", s->m_node->m_name);
#endif
				ctrl->GetSealCtrlAi()->SetSleeping(false);
			}
		}
	}

issue:
	{
		CSealUnit *unit = CSealUnit::GetUnitByTeam(task->m_team);

		if (unit != NULL)
			unit->IssueCommand(seal, (FT_COMMAND)cmd, target, false);
	}

	*dT = 0.0f;
	return true;
}

/* @socom-skeleton body Parse__7CTDebugFP5_zrdr */
_zanim_cmd_hdr* CTDebug::Parse(_zrdr* reader)
{
	/* 0x2bdc90 (written, untested): the command's first value: a number turns the AI debug
	 * output on / off ("Enabling DEBUG" / "Disabling DEBUG info" as the text), a string is a
	 * text to print (m_enable -1); anything else: no record. ELF quirks kept: a list without
	 * values is read through NULL in the ELF (port: no record); the record's command type is
	 * not set (the loader's) */
	_zrdr *value = reader->IsArray() && reader->array->integer - 1 != 0 ? &reader->array[1] : NULL;
	s32 enable = -1;
	const char *text = NULL;

	if (value == NULL)
		return NULL;

	if (value->type == ZRDR_INTEGER)
	{
		enable = value->integer;
		text = enable != 0 ? "Enabling DEBUG" : "Disabling DEBUG info";
	}
	else if (value->type == ZRDR_STRING)
	{
		text = value->string;
	}

	if (text == NULL)
		return NULL;

	u32 len = strlen(text);

	if (len & 3)
		len += 4 - (len & 3);

	u32 size = len + 16;
	TASK_DEBUG *task = (TASK_DEBUG *)_calloc(size, 1, "seal_tasks.cpp", 27);
	task->m_cmd.data_size = size;
	strcpy(task->m_text, text);
	task->m_enable = enable;
	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__7CTDebugFP14_zanim_cmd_hdrPf */
bool CTDebug::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2bdb70: the AI's debug output is switched (1 / 0) and the text goes to it. A select
	 * without a seal or controller uses up the frame's time. */
	TASK_DEBUG *task = reinterpret_cast<TASK_DEBUG *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrl *ctrl = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control) : NULL;
	CSealCtrlAi *ai = ctrl != NULL ? ctrl->GetSealCtrlAi() : NULL;

	if (seal == NULL || ctrl == NULL)
	{
		*dT = 0.0f;
		return true;
	}

	if (ai == NULL)
		return true;

	if (task->m_enable == 1)
		ai->SetDebug(true);
	else if (task->m_enable == 0)
		ai->SetDebug(false);

	ai->Debug("%s\n", task->m_text);
	return true;
}

