/* @socom-skeleton body Parse__7CTEventFP5_zrdr */
_zanim_cmd_hdr* CTEvent::Parse(_zrdr* reader)
{
	/* 0x2bd860 (written, untested): "type" (CAiEvent::GetEventFromString, GENERIC (1) by
	 * default), "pos", "node" (the anim's node argument: pos in its space), "range",
	 * "duration", "vis" (its presence) */
	TASK_EVENT *task = (TASK_EVENT *)task_alloc(36, *(u16 *)&ai_cmdid[0]);
	task->m_pos = CPnt3D::zero;
	task->m_type = 1;
	task->m_type = (s8)CAiEvent::GetEventFromString(zrdr_findstring(reader, "type"), (CAiEvent::EVENT)1);
	zrdr_findPNT3D(reader, "pos", &task->m_pos);
	char *node = zrdr_findstring(reader, "node");

	if (node != NULL)
	{
		task->m_node = ZAnim.m_CurAnim->LoadNodeNames(NULL, node, 0, 1);
		task->m_has_node = 1;
	}

	if (zrdr_findreal(reader, "range", &task->m_range, 1))
		task->m_has_range = 1;

	if (zrdr_findreal(reader, "duration", &task->m_duration, 1))
		task->m_has_duration = 1;

	if (zrdr_findtag(reader, "vis") != NULL)
		task->m_visible = 1;

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Begin__7CTEventFP14_zanim_cmd_hdr */
void CTEvent::Begin(_zanim_cmd_hdr* header)
{

}

/* @socom-skeleton body Tick__7CTEventFP14_zanim_cmd_hdrPf */
bool CTEvent::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2bd5e0: an AI event the AIs around react to (scripted noise at a door or a switch):
	 * the task's type and position (in the anim node's space with a node), its range and
	 * duration (no expiry without one), visible or heard; owned by the select seal. Always
	 * done. */
	TASK_EVENT *task = reinterpret_cast<TASK_EVENT *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);

	if (seal != NULL)
		static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi(); /* ELF: called, the answer dropped */

	CAiEvent *event = CAiEvent::Acquire();
	event->m_duration = task->m_has_duration ? task->m_duration : CAiEvent::NoExpire;

	if (task->m_has_range)
		event->m_rangeSq = task->m_range * task->m_range;

	event->m_visible = task->m_visible ? 1 : 0;
	CPnt3D pos = CPnt3D::zero;

	if (task->m_has_node)
	{
		zdb::CNode *node = ZAnim.m_CurAnim->GetNode(task->m_node, false);

		if (node != NULL)
		{
			CMatrix mtw;
			sceVu0UnitMatrix(mtw.m_matrix);
			node->BuildMTW(mtw);
			/* ELF: the VU0 multiply-add (vmulax/vmadday/vmaddaz/vmaddw) inlined */
			const CPnt3D &p = task->m_pos;
			pos.x = mtw.m_matrix[0][0] * p.x + mtw.m_matrix[1][0] * p.y + mtw.m_matrix[2][0] * p.z + mtw.m_matrix[3][0];
			pos.y = mtw.m_matrix[0][1] * p.x + mtw.m_matrix[1][1] * p.y + mtw.m_matrix[2][1] * p.z + mtw.m_matrix[3][1];
			pos.z = mtw.m_matrix[0][2] * p.x + mtw.m_matrix[1][2] * p.y + mtw.m_matrix[2][2] * p.z + mtw.m_matrix[3][2];
		}
	}
	else
	{
		pos = task->m_pos;
	}

	event->m_pos = pos;

	if (seal != NULL)
		event->m_owner = seal->m_id;

	event->m_type = (s8)task->m_type;
	CAiEvent::Create(event);
	return true;
}

/* @socom-skeleton body Parse__10CTFireModeFP5_zrdr */
_zanim_cmd_hdr* CTFireMode::Parse(_zrdr* reader)
{
	/* 0x2bd3a0 (written, untested): the weapon hint (quiet 0, again 2, auto 1, burst 1),
	 * "weapon" (a kit index), "trigger" (down, up; 0.1 / 0.8 by default), "fullauto" or
	 * "burst" (their presence: required) */
	TASK_FIREMODE *task = (TASK_FIREMODE *)task_alloc(28, *(u16 *)&ai_cmdid[0]);
	task->m_dn_time = 0.100000002f /* 0x3dcccccd */;
	task->m_up_time = 0.800000012f /* 0x3f4ccccd */;
	task->m_hint.m_quiet = 0;
	task->m_hint.m_quiet_again = 2;
	task->m_hint.m_auto = 1;
	task->m_hint.m_burst = 1;
	task->m_hint.m_use_accuracy = 0;
	task->m_hint.m_range = 0.0f;
	task->m_hint.m_use_index = 0;
	s32 weapon;

	if (zrdr_findint(reader, "weapon", &weapon, 1))
	{
		task->m_hint.m_index = weapon & 0xf;
		task->m_hint.m_use_index = 1;
	}

	PNT2D trigger;

	if (zrdr_findPNT2D(reader, "trigger", &trigger))
	{
		task->m_trigger |= 1;
		task->m_dn_time = trigger.x;
		task->m_up_time = trigger.y;
	}

	if (zrdr_findtag(reader, "fullauto") != NULL)
		task->m_hint.m_auto = 3;
	else if (zrdr_findtag(reader, "burst") != NULL)
		task->m_hint.m_burst = 3;

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Begin__10CTFireModeFP14_zanim_cmd_hdr */
void CTFireMode::Begin(_zanim_cmd_hdr* header)
{
	/* 0x2bd1a0: the seal takes the weapon the hint names (ChooseWeapon); a given trigger timing
	 * replaces its burst timing (fixed down / up times, the count restarted as ResetTrigger
	 * does, inlined); fire is no longer held; a required full auto (3) or burst sets the fire
	 * mode. m8: two uses (on_aware4), kit item 0, trigger 0.2 s down / 3.5 s up. */
	TASK_FIREMODE *task = reinterpret_cast<TASK_FIREMODE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (ai == NULL)
		return;

	ai->ChooseWeapon(task->m_hint);

	if (task->m_trigger & 1)
	{
		CAiTrigger &trigger = ai->m_ai_trigger;
		trigger.m_dn_time.m_min = task->m_dn_time;
		trigger.m_dn_time.m_range = 0.0f;
		trigger.m_up_time.m_min = task->m_up_time;
		trigger.m_up_time.m_range = 0.0f;
		f32 up = trigger.m_up_time.m_range == 0.0f ? trigger.m_up_time.m_min
			: trigger.m_up_time.m_min + trigger.m_up_time.m_range * ((f32)rand() * 4.656613e-10f);
		trigger.m_marker = up;
		f32 dn = trigger.m_dn_time.m_range == 0.0f ? trigger.m_dn_time.m_min
			: trigger.m_dn_time.m_min + trigger.m_dn_time.m_range * ((f32)rand() * 4.656613e-10f);
		trigger.m_timer = (f32)((double)trigger.m_marker + (double)dn);
	}

	ai->SetHoldFire(false);

	if (task->m_hint.m_auto == 3)
		seal->m_kit.SetCurFireMode((FIREMODE)3);
	else if (task->m_hint.m_burst == 3)
		seal->m_kit.SetCurFireMode((FIREMODE)2);
}

