/* @socom-skeleton body GetSignalByName__8CTSignalFPCc */
AiSig CTSignal::GetSignalByName(const char* signal)
{
	return AiSig::AISIG_UNKNOWN;
}

/* @socom-skeleton body Parse__8CTSignalFP5_zrdr */
_zanim_cmd_hdr* CTSignal::Parse(_zrdr* reader)
{
	/* 0x2b6d60 (written, untested): "signal" (GetSignalByName), "entity"; with neither, the
	 * command's single string value is the signal; a bare command: AISIG_ANIMCOMPLETE.
	 * ELF quirk kept: the record's command type is not set (the loader's) */
	char *signal = zrdr_findstring(reader, "signal");
	char *entity = zrdr_findstring(reader, "entity");
	s32 count = reader->IsArray() ? reader->array->integer - 1 : 0;

	if (signal == NULL && entity == NULL && count == 1 && reader->array[1].type == ZRDR_STRING)
		signal = reader->array[1].string;

	if (signal == NULL && count == 0)
		signal = const_cast<char *>("AISIG_ANIMCOMPLETE");

	if (signal == NULL)
		return NULL;

	u32 len = entity != NULL ? strlen(entity) : 0;

	if (len & 3)
		len += 4 - (len & 3);

	u32 size = len + 16;
	TASK_SIGNAL *task = (TASK_SIGNAL *)_calloc(size, 1, "seal_tasks.cpp", 27);
	task->m_cmd.data_size = size;
	*(u32 *)&task->m_signal = (u8)CTSignal::GetSignalByName(signal);

	if (entity != NULL)
		strcpy(task->m_entity, entity);
	else
		task->m_entity[0] = '\0';

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__8CTSignalFP14_zanim_cmd_hdrPf */
bool CTSignal::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b6c50: the anim signal (AISIG_ANIMCOMPLETE...) for the AI controller of the select's
	 * seal, or of the named seal entity when the task names one (none when that is no seal);
	 * a seal without AI (the player using an action) gets nothing. The frame's time is used
	 * up. ELF quirk kept: the select's controller is not NULL-tested. */
	TASK_SIGNAL *task = reinterpret_cast<TASK_SIGNAL *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (task->m_entity[0] != 0)
	{
		CEntity *entity = CEntity::m_list.GetEntity(task->m_entity);

		if (entity != NULL && (u8)entity->m_type == CEntity::ENT_TYPE_SEAL)
			ai = static_cast<CSealCtrl *>(entity->m_control)->GetSealCtrlAi();
		else
			ai = NULL;
	}

	if (ai != NULL)
		ai->AnimSignal(ZAnim.m_CurAnim, (AI_SIGNAL)task->m_signal);

	*dT = 0.0f;
	return true;
}

struct TASK_SOUND : public TASK_HDR /* ai::SOUND (Tick 0x2b64b0) */
{
	/* +0x08: one word of bits (Parse 0x2b6840, Tick 0x2b64b0) */
	u32 m_wait : 1;             /* bit 0 "blocking": the task holds while the sound plays */
	u32 m_sitrep : 1;           /* bit 1 "sitrep": the sound's +0x20 set to 2 */
	u32 m_broadcast : 1;        /* bit 2 "broadcast": played on the seal (else at its position) */
	u32 m_aware : 4;            /* bits 3-6: the most aware the seal may be (Parse leaves 0) */
	u32 m_unused : 1;
	u32 m_pending : 1;          /* bit 8: set by Begin */
	u32 m_num_names : 8;        /* bits 9-16: the sound names */
	u32 m_count : 8;            /* bits 17-24: the command's values (the pick's range) */
	u32 m_unused2 : 7;
	CSndInstance *m_instance;   /* +0x0c */
	char m_names[4];            /* +0x10 the entity's name, then the sound names */
};

/* @socom-skeleton body Parse__7CTSoundFP5_zrdr */
_zanim_cmd_hdr* CTSound::Parse(_zrdr* reader)
{
	/* 0x2b6840 (written, untested): "name" (or "NAME"): a list of sound names (none, or no
	 * string in it: no record); "entity"; "blocking", "sitrep", "broadcast" (their presence).
	 * The entity's name comes first in the record, then the sound names. ELF quirk kept: the
	 * names are copied from the first m_names values only (a value that is not a string
	 * there drops a later name) */
	_zrdr *tag = zrdr_findtag(reader, "name");

	if (tag == NULL)
		tag = zrdr_findtag(reader, "NAME");

	if (tag == NULL || !tag->IsArray())
		return NULL;

	s32 count = tag->array->integer - 1;
	s32 names = 0;
	u32 bytes = 0;

	for (s32 i = 0; i < count; i++)
	{
		_zrdr *v = tag->Get(i);

		if (v != NULL && v->type == ZRDR_STRING)
		{
			bytes += strlen(v->string) + 1;
			names++;
		}
	}

	if (names <= 0)
		return NULL;

	char *entity = zrdr_findstring(reader, "entity");
	u32 len = (entity != NULL ? strlen(entity) : 0) + bytes;

	if (len & 3)
		len += 4 - (len & 3);

	TASK_SOUND *task = (TASK_SOUND *)task_alloc(len + 20, *(u16 *)&ai_cmdid[0]);

	if (entity != NULL)
		strcpy(task->m_names, entity);
	else
		task->m_names[0] = '\0';

	s32 copied = 1;

	for (s32 i = 0; i < names; i++)
	{
		_zrdr *v = tag->Get(i);

		if (v == NULL || v->type != ZRDR_STRING)
			continue;

		char *p = task->m_names;

		for (s32 k = copied; k != 0; k--)
			p += strlen(p) + 1;

		strcpy(p, v->string);
		copied++;
	}

	task->m_num_names = names;
	task->m_count = count;

	if (zrdr_findtag(reader, "blocking") != NULL)
		task->m_wait = 1;

	if (zrdr_findtag(reader, "sitrep") != NULL)
		task->m_sitrep = 1;

	if (zrdr_findtag(reader, "broadcast") != NULL)
		task->m_broadcast = 1;

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Begin__7CTSoundFP14_zanim_cmd_hdr */
void CTSound::Begin(_zanim_cmd_hdr* header)
{
	/* 0x2b6820: the sound is due; no instance yet */
	TASK_SOUND *task = reinterpret_cast<TASK_SOUND *>(header);
	task->m_pending = 1;
	task->m_instance = NULL;
}

/* @socom-skeleton body End__7CTSoundFP14_zanim_cmd_hdr */
void CTSound::End(_zanim_cmd_hdr* header)
{
	/* 0x2b67e0: the instance is let finish on its own */
	TASK_SOUND *task = reinterpret_cast<TASK_SOUND *>(header);

	if (task->m_instance != NULL)
		task->m_instance->TerminateOnFinish();

	task->m_instance = NULL;
}

/* @socom-skeleton body Tick__7CTSoundFP14_zanim_cmd_hdrPf */
bool CTSound::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b64b0: once, one of the task's sounds (picked at random from the names after the
	 * entity name; the entity, else the select's seal) is played by a seal whose AI is not
	 * more aware than m_aware: on it (broadcast) or at its position (sitrep: the sound's
	 * +0x20 set to 2). The task then holds while the instance plays when m_wait is set (ELF:
	 * the answer is IsPlaying itself), else it is done. The bits at +0x8 as Parse 0x2b6840
	 * writes them (part 4: before, the port read +0x8 as one byte and +0xa as the count) */
	TASK_SOUND *task = reinterpret_cast<TASK_SOUND *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	bool done = true;

	if (task->m_pending)
	{
		const char *entity = task->m_names;
		u32 pick = task->m_count - 1 != 0 ? (u32)(rand() % task->m_count) + 1 : 1;
		const char *name = NULL;

		if (!(task->m_num_names < pick)) /* ELF quirk kept: the pick ranges over all the values */
		{
			name = task->m_names;

			for (u32 i = pick; i != 0; i--)
				name += strlen(name) + 1;
		}

		if (name == NULL)
		{
			*dT = 0.0f;
			return true;
		}

		if (entity[0] != '\0')
		{
			CEntity *e = CEntity::m_list.GetEntity(entity);
			seal = e != NULL && e->m_type == CEntity::ENT_TYPE_SEAL ? static_cast<CZSealBody *>(e) : NULL;
		}

		if (seal != NULL)
		{
			CSealCtrl *ctrl = static_cast<CSealCtrl *>(seal->m_control);
			u32 aware = 0;

			if (ctrl != NULL && ctrl->IsAi())
				aware = ctrl->GetSealCtrlAi()->GetAiAware();

			if (!((u32)task->m_aware < aware))
			{
				CSnd *snd = CSnd::GetSoundByName(name);

				if (snd != NULL)
				{
					if (task->m_sitrep)
						*((u8 *)snd + 0x20) = 2; /* port: CSnd +0x20 unnamed */

					if (task->m_broadcast)
						task->m_instance = snd->PlaySound((CSndInstance *)NULL, seal->m_id);
					else
						task->m_instance = snd->PlaySound3D(seal->GetPosW(), 1.0f, 0, NULL, seal->m_id);
				}
			}
		}

		task->m_pending = 0;
	}

	if (!task->m_pending && task->m_wait && task->m_instance != NULL)
		done = task->m_instance->IsPlaying();

	*dT = 0.0f;
	return done;
}

/* @socom-skeleton body Parse__9CTSpecialFP5_zrdr */
_zanim_cmd_hdr* CTSpecial::Parse(_zrdr* reader)
{
	/* 0x2b6450 (written, untested): no arguments; the record type is ai::SPECIAL's own id */
	return task_alloc(12, *(u16 *)&ai_cmdid[12]);
}

/* @socom-skeleton body Begin__9CTSpecialFP14_zanim_cmd_hdr */
void CTSpecial::Begin(_zanim_cmd_hdr* header)
{
	/* 0x2b63d0: from the anim's first argument command (index 1), phase 0 */
	TASK_SPECIAL *task = reinterpret_cast<TASK_SPECIAL *>(header);
	TASK_SELECT *select = reinterpret_cast<TASK_SELECT *>(taskFindParam(*(u16 *)&ai_cmdid[8], task->m_seal_index));
	CSealCtrlAi *ai = select != NULL ? select->m_ai : NULL;

	if (ai != NULL) /* port: tested (ELF: Debug on a NULL controller) */
		ai->Debug("CTSpecial::BEGIN\n");

	task->m_index = 1;
	task->m_phase = 0;
}

/* @socom-skeleton body End__9CTSpecialFP14_zanim_cmd_hdr */
void CTSpecial::End(_zanim_cmd_hdr* header)
{
	/* 0x2b62d0: the anim's argument commands from index 1 on are wiped (10s) and freed (they
	 * are built at run time for the special); back to index 1, phase 0 */
	TASK_SPECIAL *task = reinterpret_cast<TASK_SPECIAL *>(header);
	TASK_SELECT *select = reinterpret_cast<TASK_SELECT *>(taskFindParam(*(u16 *)&ai_cmdid[8], task->m_seal_index));
	CSealCtrlAi *ai = select != NULL ? select->m_ai : NULL;

	if (ai != NULL) /* port: tested (ELF: Debug on a NULL controller) */
		ai->Debug("CTSpecial::COMPLETE\n");

	for (int i = 1;; i++)
	{
		CZAnimArgList *args = ZAnim.m_CurAnim->m_arg_list;
		_zanim_cmd_hdr *cmd = args != NULL ? args->GetCmd(i) : NULL;

		if (cmd == NULL)
			break;

		memset(cmd, 10, cmd->data_size);
		_free(cmd, "seal_tasks.cpp", 2768);
	}

	task->m_index = 1;
	task->m_phase = 0;
}

/* @socom-skeleton body Tick__9CTSpecialFP14_zanim_cmd_hdrPf */
bool CTSpecial::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b6150: runs the anim's argument commands one after another as sub-commands (each
	 * one's Begin, Tick until done, End); done when there is none left */
	TASK_SPECIAL *task = reinterpret_cast<TASK_SPECIAL *>(header);
	CZAnimArgList *args = ZAnim.m_CurAnim->m_arg_list;
	_zanim_cmd_hdr *cmd = args != NULL ? args->GetCmd(task->m_index) : NULL;
	zanim_cmd *entry = cmd != NULL ? ZAnim.GetCmdEntry((unsigned short)cmd->data_type) : NULL;
	bool done = true;

	if (entry != NULL)
	{
		done = false;

		if (task->m_phase == 0)
		{
			if (entry->begin != NULL)
				reinterpret_cast<void (*)(_zanim_cmd_hdr *)>(entry->begin)(cmd);

			task->m_phase = 1;
		}

		if (task->m_phase == 1 && entry->tick != NULL && reinterpret_cast<bool (*)(_zanim_cmd_hdr *, float *)>(entry->tick)(cmd, dT))
			task->m_phase = 2;

		if (task->m_phase == 2)
		{
			if (entry->end != NULL)
				reinterpret_cast<void (*)(_zanim_cmd_hdr *)>(entry->end)(cmd);

			task->m_phase = 0;
			task->m_index++;
		}
	}

	*dT = 0.0f;
	return done;
}

/* @socom-skeleton body Parse__8CTStanceFP5_zrdr */
_zanim_cmd_hdr* CTStance::Parse(_zrdr* reader)
{
	/* 0x2b6010 (written, untested): "stance" (get_stance), "peek" (left -1, right 1, up 0,
	 * else 2), "delay" (0) */
	char *stance = zrdr_findstring(reader, "stance");
	char *peek = zrdr_findstring(reader, "peek");
	f32 delay = 0.0f;
	zrdr_findreal(reader, "delay", &delay, 1);
	s32 st = (s8)sealai::get_stance(stance);
	s32 pk = 2;

	if (peek != NULL)
	{
		if (strcmp(peek, "left") == 0)
			pk = -1;
		else if (strcmp(peek, "right") == 0)
			pk = 1;
		else if (strcmp(peek, "up") == 0)
			pk = 0;
	}

	TASK_STANCE *task = (TASK_STANCE *)task_alloc(24, *(u16 *)&ai_cmdid[0]);
	task->m_delay = delay;
	task->m_peek = (s8)pk;
	task->m_stance = st;
	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Begin__8CTStanceFP14_zanim_cmd_hdr */
void CTStance::Begin(_zanim_cmd_hdr* header)
{
	/* 0x2b5f70: the stance and the peek are set, the delay starts */
	TASK_STANCE *task = reinterpret_cast<TASK_STANCE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (ai == NULL)
		return;

	ai->SetStance((SEAL_STANCE)(s8)task->m_stance);
	seal->m_desiredPeek = (SEAL_PEEK)(s8)task->m_peek;
	task->m_timer = task->m_delay;

}

/* @socom-skeleton body End__8CTStanceFP14_zanim_cmd_hdr */
void CTStance::End(_zanim_cmd_hdr* header)
{
	/* 0x2b5eb0: a peek held for a while ends */
	TASK_STANCE *task = reinterpret_cast<TASK_STANCE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (ai != NULL && task->m_delay != 0.0f && task->m_peek != 2)
		seal->m_desiredPeek = (SEAL_PEEK)2;

}

/* @socom-skeleton body Tick__8CTStanceFP14_zanim_cmd_hdrPf */
bool CTStance::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b5de0: done when the delay has run out; the frame's time is used up */
	TASK_STANCE *task = reinterpret_cast<TASK_STANCE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (ai == NULL)
	{
		*dT = 0.0f;
		return true;
	}

	task->m_timer -= *dT;
	*dT = 0.0f;
	return task->m_timer <= 0.0f;
}

/* @socom-skeleton body Parse__7CTStateFP5_zrdr */
_zanim_cmd_hdr* CTState::Parse(_zrdr* reader)
{
	/* 0x2b5bd0 (written, untested): "push" (the state, get_state; none / 0: no record);
	 * RUSH (29): "entity", "timer", "range", "contact" (its presence: flag 4); FOLLOW (9):
	 * "entity" (required) and "offset" ((0, 0, 20) by default) */
	char *push = zrdr_findstring(reader, "push");

	if (push == NULL)
		return NULL;

	AI_STATE st = sealai::get_state(push);
	u8 state = (u8)st;

	if (state == 0)
		return NULL;

	char *name = NULL;

	if (state == 29 || state == 9)
		name = zrdr_findstring(reader, "entity");

	if (state == 9 && name == NULL)
		return NULL;

	u32 len = name != NULL ? strlen(name) : 0;

	if (len & 3)
		len += 4 - (len & 3);

	TASK_STATE *task = (TASK_STATE *)task_alloc(len + 40, *(u16 *)&ai_cmdid[0]);
	*(u32 *)&task->m_state = state;

	if (name != NULL)
		strcpy(task->m_names, name);
	else
		task->m_names[0] = '\0';

	if (state == 29)
	{
		zrdr_findreal(reader, "timer", &task->m_time, 1);
		zrdr_findreal(reader, "range", &task->m_offset.x, 1);

		if (zrdr_findtag(reader, "contact") != NULL)
			task->m_flags = 4;
	}
	else if (state == 9)
	{
		task->m_offset.x = 0.0f;
		task->m_offset.y = 0.0f;
		task->m_offset.z = 20.0f;
		zrdr_findPNT3D(reader, "offset", &task->m_offset);
	}

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__7CTStateFP14_zanim_cmd_hdrPf */
bool CTState::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b5820: the AI state is pushed (critical); a FOLLOW state gets its master (the
	 * entity named after the task's strings) and offset (+0x18), a RUSH state its
	 * parameters (+0x14 time, +0x18 range squared, flags +0xc) and target (that seal, else
	 * the AI's target); always done. A time / range of 0 clears its flag (1 / 2); the target
	 * name is the first of the task's strings. ELF: the new top state is not NULL-tested. */
	TASK_STATE *task = reinterpret_cast<TASK_STATE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;
	*dT = 0.0f;

	if (ai == NULL)
		return true;

	u8 state = task->m_state;

	if (!ai->PushAiState((AI_STATE)state, true))
		return true;

	CAiState *top = ai->GetAiState();

	if (state == STATE_FOLLOW)
	{
		CAiState *follow = top->m_state == STATE_FOLLOW ? top : NULL;
		CEntity *e = CEntity::m_list.GetEntity(task->m_names);
		CZSealBody *master = e != NULL && (u8)e->m_type == 2 ? static_cast<CZSealBody *>(e) : NULL;

		if (master != NULL)
		{
			ai->SetFollowMaster(master);
			ai->SetFollowOffset(&task->m_offset);
			follow->m_setup = 1;
		}
	}
	else if (state == STATE_RUSH)
	{
		CAiSRush *rush = top->m_state == STATE_RUSH ? static_cast<CAiSRush *>(top) : NULL;
		f32 time = task->m_time;
		rush->m_time = time;

		if (0.0f == time)
			rush->m_option_flags &= ~1u;
		else
			rush->m_option_flags |= 1;

		f32 range = task->m_offset.x;
		rush->m_range_sq = range * range;

		if (0.0f == range)
			rush->m_option_flags &= ~2u;
		else
			rush->m_option_flags |= 2;

		rush->m_option_flags |= task->m_flags;
		CEntity *e = CEntity::m_list.GetEntity(task->m_names);
		CZSealBody *target = e != NULL && (u8)e->m_type == 2 ? static_cast<CZSealBody *>(e) : NULL;

		if (target != NULL)
		{
			rush->SetTarget(target);
			rush->m_setup = 1;
		}
		else
		{
			CEntity *te = ai->m_target.m_target.m_ent;

			if (te != NULL && te->m_isAlive)
			{
				rush->SetTarget((u8)te->m_type == 2 ? static_cast<CZSealBody *>(te) : NULL);
				rush->m_setup = 1;
			}
		}
	}

	return true;
}

/* @socom-skeleton body Parse__9CTStopAllFP5_zrdr */
_zanim_cmd_hdr* CTStopAll::Parse(_zrdr* reader)
{
	/* 0x2b5750 (written, untested): the command's own true / false (default true: the AI
	 * off), "inactive"; the flags byte Tick reads (bit 0 off, bit 1 inactive) */
	bool off = true;
	zrdr_tobool(reader, &off);
	bool inactive = zrdr_findtag(reader, "inactive") != NULL;
	_zanim_cmd_hdr *task = task_alloc(12, *(u16 *)&ai_cmdid[0]);
	u8 *flags = reinterpret_cast<u8 *>(task) + 8;
	*flags = (u8)((*flags & ~1) | (off ? 1 : 0));
	*flags = (u8)((*flags & ~2) | (inactive ? 2 : 0));
	return task;
}

/* @socom-skeleton body Tick__9CTStopAllFP14_zanim_cmd_hdrPf */
bool CTStopAll::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b5700: ai::STOPALL (true / false): the AI off (bit 0 of the byte at +8) or on;
	 * bit 1 is passed inverted as the second argument */
	u8 flags = reinterpret_cast<u8*>(header)[8];
	CSealCtrlAi::SetAiEnabled((flags & 1) == 0, (flags & 2) == 0);
	return true;
}

/* ai::INRANGE record (Tick 0x2b53f0) */
struct TASK_RANGE : public TASK_HDR
{
	f32 m_range;      /* +0x08 compared with the squared distance (Parse squares it) */
	s32 m_entity;     /* +0x0c the entity's id: CEntity::invalidId none, -3 not looked up yet */
	char m_name[4];   /* +0x10 the entity's name ("player": the first entity) */
};

/* @socom-skeleton body Parse__7CTRangeFP5_zrdr */
_zanim_cmd_hdr* CTRange::Parse(_zrdr* reader)
{
	/* 0x2b55d0 (written, untested): "entity" (kept by name, looked up on the first tick),
	 * "range" (1000 by default; kept squared) */
	char *name = zrdr_findstring(reader, "entity");
	f32 range = 1000.0f;
	zrdr_findreal(reader, "range", &range, 1);
	u32 len = name != NULL ? strlen(name) : 0;

	if (len & 3)
		len += 4 - (len & 3);

	TASK_RANGE *task = (TASK_RANGE *)task_alloc(len + 20, *(u16 *)&ai_cmdid[0]);
	task->m_range = range * range;
	task->m_entity = name != NULL ? -3 /* unknownId 0x44cd80 */ : CEntity::invalidId;

	if (name != NULL)
		strcpy(task->m_name, name);
	else
		task->m_name[0] = '\0';

	return (_zanim_cmd_hdr *)task;
}


/* the entity of a task's id / name (inline in CTRange::Tick and CTRegion::Tick): invalidId
 * none, -3 (unknownId 0x44cd80) looked up by name once ("player" is the first entity), else by
 * its id */
static CEntity *taskEntity(s32 &id, const char *name)
{
	if (id == CEntity::invalidId)
		return NULL;

	if (id != -3)
		return CEntity::m_list.GetEntityById((u32)id);

	CEntity *e = CEntity::m_list.GetEntity(name);

	if (e == NULL && strcasecmp(name, "player") == 0)
		e = CEntity::m_list.GetEntityByIndex(0);

	if (e != NULL)
		id = (s32)e->m_id;

	return e;
}

/* @socom-skeleton body Tick__7CTRangeFP14_zanim_cmd_hdrPf */
bool CTRange::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b53f0 (Snow3's on_aware0: Snow2 within 40): whether the entity is within the range of
	 * the select's seal; done at once (time used up) without the seal or its controller */
	TASK_RANGE *task = reinterpret_cast<TASK_RANGE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);

	if (seal == NULL || seal->m_control == NULL)
	{
		*dT = 0.0f;
		return true;
	}

	CEntity *e = taskEntity(task->m_entity, task->m_name);

	if (e == NULL)
		return false;

	CPnt3D d;
	seal->GetPosW()->Sub(e->GetPosW(), &d);
	return d.x * d.x + d.y * d.y + d.z * d.z <= task->m_range;
}

/* ai::INREGION record (Tick 0x2b4c50) */
struct TASK_REGION : public TASK_HDR
{
	CAiMapLoc m_loc;           /* +0x08 the region's location (map id, x, y) */
	CAiMap::region *m_region;  /* +0x0c looked up from m_loc, again when AiMaps' cookie changes */
	u8 m_team;                 /* +0x10 a team's bit number: any live member of it (0: an entity) */
	u8 m_cookie;               /* +0x11 AiMaps.m_cookie at the lookup */
	u16 m_pickup;              /* +0x12 non-zero: a pickup mode (see Tick) */
	s32 m_entity;              /* +0x14 the entity's id: invalidId: the select's seal, -3 by name */
	char m_name[4];            /* +0x18 the entity's name ("player": the first entity) */
};

/* @socom-skeleton body Parse__8CTRegionFP5_zrdr */
_zanim_cmd_hdr* CTRegion::Parse(_zrdr* reader)
{
	/* 0x2b5260 (written, untested): "entity" (by name, else the select's seal), "region"
	 * (AiMaps' region of that name), "weapon" (the pickup mode: that weapon id), "team" (a
	 * team bit number). port: the location starts invalid (the ELF keeps the stack's word
	 * when the region is not found) */
	char *name = zrdr_findstring(reader, "entity");
	char *region = zrdr_findstring(reader, "region");
	char *weapon = zrdr_findstring(reader, "weapon");
	u32 team = 0;
	zrdr_finduint(reader, "team", &team, 1);
	CAiMapLoc loc;
	memcpy(&loc, CAiMapLoc::invalid, 4);
	AiMaps.GetRegion(region, loc);
	u32 len = name != NULL ? strlen(name) : 0;

	if (len & 3)
		len += 4 - (len & 3);

	TASK_REGION *task = (TASK_REGION *)task_alloc(len + 28, *(u16 *)&ai_cmdid[0]);
	task->m_loc = loc;
	task->m_region = NULL;
	task->m_team = (u8)team;
	task->m_pickup = 0;
	task->m_entity = name != NULL ? -3 /* unknownId 0x44cd80 */ : CEntity::invalidId;
	task->m_cookie = 0;

	if (name != NULL)
		strcpy(task->m_name, name);
	else
		task->m_name[0] = '\0';

	if (weapon != NULL)
		task->m_pickup = (u8)CZWeapon::GetWeaponId(weapon);

	return (_zanim_cmd_hdr *)task;
}


/* inline in CTRegion::Tick: a location inside the region (same map, within its extent) */
static bool regionHolds(const CAiMap::region *region, const CAiMapLoc &task, const CAiMapLoc &loc)
{
	if (task.m_mapid != loc.m_mapid)
		return false;

	s32 dx = (s32)loc.x - (s32)region->m_loc.x;
	s32 dy = (s32)loc.y - (s32)region->m_loc.y;
	return dx >= 0 && dx < (s32)region->m_dx && dy >= 0 && dy < (s32)region->m_dy;
}

/* @socom-skeleton body Tick__8CTRegionFP14_zanim_cmd_hdrPf */
bool CTRegion::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b4c50 (the m8 objectives: InsertObj, SearchLodge, Extract...): whether the entity -
	 * the select's seal (id invalidId), a named one, or any live member of a team (m_team: its
	 * bit number) - stands in the AI map region (by its m_mapLoc). The region is looked up
	 * again when AiMaps' cookie changed. A missing entity clears the name's first byte.
	 * The pickup mode (m_pickup != 0, 0x2b4ccc): any pickup of types 4-7 whose data's +0xc
	 * object has the id m_pickup at +0x60 (the place of CZFTSWeapon::m_ID), by
	 * CAiMaps::GetLocation of its position (written, untested: no script of the m8 disc
	 * uses it, and the port names no pickup types 4-7; their data layout is not known). */
	TASK_REGION *task = reinterpret_cast<TASK_REGION *>(header);
	CAiMap::region *region;

	if (task->m_region != NULL && task->m_cookie == AiMaps.m_cookie)
	{
		region = task->m_region;
	}
	else
	{
		task->m_cookie = AiMaps.m_cookie;
		region = AiMaps.GetRegion(task->m_loc);
		task->m_region = region;
	}

	if (region == NULL)
		return false;

	if (task->m_pickup != 0)
	{
		std::list<CPickup *>::iterator it = CPickup::GetFirst();
		bool in = false;

		for (CPickup *pickup = CPickup::GetNext(it, CPickup::PU_NONE); !in && pickup != NULL; pickup = CPickup::GetNext(it, CPickup::PU_NONE))
		{
			u32 type = pickup->m_type;

			if (type < 4 || type > 7 || pickup->m_data == NULL)
				continue;

			/* port: raw reads, the layout of these pickups' data is not known */
			const u8 *object = *(const u8 *const *)((const u8 *)pickup->m_data + 0xc);

			if (object == NULL || object[0x60] != task->m_pickup)
				continue;

			CAiMapLoc loc;

			if (AiMaps.GetLocation(pickup->GetPosW(), loc))
				in = regionHolds(region, task->m_loc, loc);
		}

		return in;
	}

	if (task->m_team == 0)
	{
		CEntity *e;

		if (task->m_entity == CEntity::invalidId)
			e = taskSeal(task->m_seal_index);
		else
			e = taskEntity(task->m_entity, task->m_name);

		if (e == NULL)
		{
			task->m_name[0] = '\0';
			return false;
		}

		return regionHolds(region, task->m_loc, e->m_mapLoc);
	}

	u32 bit = 1u << task->m_team;

	for (CEntityList::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
	{
		CEntity *e = *it;

		if (e != NULL && e->m_isAlive && (bit & e->m_team) != 0 && regionHolds(region, task->m_loc, e->m_mapLoc))
			return true;
	}

	return false;
}

/* ai::TEAM record (Tick 0x2b49f0) */
struct TASK_TEAM : public TASK_HDR
{
	u32 m_mask; /* +0x08 team bits */
	s32 m_op;   /* +0x0c 0 add them, 1 remove them, 2 nothing */
};

/* @socom-skeleton body Parse__6CTTeamFP5_zrdr */
_zanim_cmd_hdr* CTTeam::Parse(_zrdr* reader)
{
	/* 0x2b4b40 (written, untested): "join" / "leave" / "ismember" with a list of team
	 * numbers (ftmask_create); none: no record */
	u32 ftmask_create(_zrdr *); /* seal_env.cpp 0x2a4bf0; no header declares it */
	s32 op = -1;
	_zrdr *tag = zrdr_findtag(reader, "join");

	if (tag != NULL)
	{
		op = 0;
	}
	else if ((tag = zrdr_findtag(reader, "leave")) != NULL)
	{
		op = 1;
	}
	else if ((tag = zrdr_findtag(reader, "ismember")) != NULL)
	{
		op = 2;
	}

	if (op == -1)
		return NULL;

	TASK_TEAM *task = (TASK_TEAM *)task_alloc(16, *(u16 *)&ai_cmdid[0]);
	task->m_op = op;
	task->m_mask = ftmask_create(tag);
	return (_zanim_cmd_hdr *)task;
}


/* @socom-skeleton body Tick__6CTTeamFP14_zanim_cmd_hdrPf */
bool CTTeam::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b49f0: the select's seal joins (0) or leaves (1) the teams of the mask, its AI's event
	 * mask follows; always done, the frame's time used up */
	TASK_TEAM *task = reinterpret_cast<TASK_TEAM *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

	if (seal != NULL && seal->m_control != NULL)
	{
		if (task->m_op == 0)
		{
			seal->SetTeamMask(seal->m_team | task->m_mask);

			if (ai != NULL)
				ai->UpdateEventMask();
		}
		else if (task->m_op == 1)
		{
			seal->SetTeamMask(seal->m_team & ~task->m_mask);

			if (ai != NULL)
				ai->UpdateEventMask();
		}
	}

	*dT = 0.0f;
	return true;
}

/* @socom-skeleton body Parse__7CTValveFP5_zrdr */
_zanim_cmd_hdr* CTValve::Parse(_zrdr* reader)
{
	/* 0x2b4510 (written, untested): values: the AI's own valve (CSealCtrlAi::get_valve; 5
	 * none: no record), then an operator (alone: that compare with 0; none: "!=" 0), then
	 * the operand: a number, or a valve name (ParseValveName: an input valve's index, else
	 * the anim's valve of that name; flags 0x8 | 0x10, 0x4 for an input valve) */
	s32 count = reader != NULL && reader->IsArray() ? reader->array->integer - 1 : 0;

	if (count == 0)
		return NULL;

	_zrdr *v = reader->array;
	const char *name = v[1].type == ZRDR_STRING ? v[1].string : NULL;

	if ((u8)CSealCtrlAi::get_valve(name) == 5)
		return NULL;

	TASK_VALVE *task = (TASK_VALVE *)task_alloc(24, *(u16 *)&ai_cmdid[0]);
	*(u32 *)&task->m_which = (u8)CSealCtrlAi::get_valve(name);
	VALVE_CMD_DATA &cmd = task->m_cmd;
	cmd.m_valve = 0;
	cmd.m_value = 0;
	cmd.m_flags &= (u8)~0x1f;

	if (count == 1)
	{
		cmd.m_op = 1;
		return (_zanim_cmd_hdr *)task;
	}

	cmd.m_op = (u8)CValve::ParseOperator(v[2].type == ZRDR_STRING ? v[2].string : NULL);

	if (count == 2)
		return (_zanim_cmd_hdr *)task;

	_zrdr *operand = &v[3];

	if (operand->type == ZRDR_STRING)
	{
		int index = -1;
		CValve *valve = VALVE_CMD_DATA::ParseValveName(operand->string, index);

		if (index != -1)
			cmd.m_value = (u32)index;
		else
			cmd.m_value = valve != NULL ? (u32)ZAnim.m_CurAnim->AddValve(valve->m_name) : 0; /* port: NULL test */

		cmd.m_flags = (u8)((cmd.m_flags & ~0x1c) | (index != -1 ? 0x4 : 0) | 0x8 | 0x10);
	}
	else
	{
		cmd.m_value = operand->type == ZRDR_INTEGER ? (u32)operand->integer : operand->type == ZRDR_REAL ? (u32)(s32)operand->real : 0;
	}

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Tick__7CTValveFP14_zanim_cmd_hdrPf */
bool CTValve::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b4450: the AI's own valve (SEAL_VALVE) is compared as the task says; without an AI
	 * it is done */
	TASK_VALVE *task = reinterpret_cast<TASK_VALVE *>(header);
	CZSealBody *seal = taskSeal(task->m_seal_index);
	CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;
	*dT = 0.0f;

	if (ai == NULL)
		return true;

	task->m_cmd.m_valve = (u32)ai->GetValve((SEAL_VALVE)task->m_which);
	bool ok = task->m_cmd.Compare();
	task->m_cmd.m_valve = 0;
	return ok;
}

/* @socom-skeleton body Parse__6CTWaitFP5_zrdr */
_zanim_cmd_hdr* CTWait::Parse(_zrdr* reader)
{
	/* 0x2b4300 (written, untested): "wait" (a time or a range); none: no record. ELF quirk
	 * kept: the timer is drawn twice */
	Rfloat wait;
	wait.m_min = 0.0f;
	wait.m_range = 0.0f;

	if (!zrdr_findRfloat(reader, "wait", &wait))
		return NULL;

	TASK_WAIT *task = (TASK_WAIT *)task_alloc(20, *(u16 *)&ai_cmdid[0]);
	task->m_wait = wait;

	for (s32 i = 0; i < 2; i++)
	{
		if (task->m_wait.m_range == 0.0f)
			task->m_timer = task->m_wait.m_min;
		else
			task->m_timer = task->m_wait.m_min + task->m_wait.m_range * ((f32)rand() * (1.0f / 2147483648.0f));
	}

	return (_zanim_cmd_hdr *)task;
}

/* @socom-skeleton body Begin__6CTWaitFP14_zanim_cmd_hdr */
void CTWait::Begin(_zanim_cmd_hdr* header)
{
	/* 0x2b4230: the wait's time is drawn (the select's controller is asked for its AI, the
	 * answer is not used) */
	TASK_WAIT *task = reinterpret_cast<TASK_WAIT *>(header);
	f32 t = task->m_wait.m_min;

	if (task->m_wait.m_range != 0.0f)
		t = task->m_wait.m_min + task->m_wait.m_range * ((f32)rand() * (1.0f / 2147483648.0f));

	task->m_timer = t;
}

/* @socom-skeleton body Tick__6CTWaitFP14_zanim_cmd_hdrPf */
bool CTWait::Tick(_zanim_cmd_hdr* header, f32* dT)
{
	/* 0x2b4030: done when the time has run out (never for -1); the time is drawn again for
	 * the next pass; the frame's time is used up */
	TASK_WAIT *task = reinterpret_cast<TASK_WAIT *>(header);
	bool done = false;

	if (task->m_timer != CAiTimer::infinite)
	{
		task->m_timer -= *dT;
		done = task->m_timer != CAiTimer::infinite && task->m_timer <= 0.0f;

		if (done)
		{
			f32 t = task->m_wait.m_min;

			if (task->m_wait.m_range != 0.0f)
				t = task->m_wait.m_min + task->m_wait.m_range * ((f32)rand() * (1.0f / 2147483648.0f));

			task->m_timer = t;
		}
	}

	*dT = 0.0f;
	return done;
}
